solution.javascript:
function serialize(root) {
  const result = [];
  function ser(node) {
    if (!node) { result.push('N'); return; }
    result.push(String(node.val));
    ser(node.left); ser(node.right);
  }
  ser(root);
  return result.join(',');
}
function deserialize(data) {
  const arr = data.split(','); let i = 0;
  function des() {
    if (arr[i] === 'N') { i++; return null; }
    const node = new TreeNode(parseInt(arr[i++]));
    node.left = des(); node.right = des();
    return node;
  }
  return des();
}

solution.cpp:
string serialize(TreeNode* root) {
    if (!root) return "N";
    return to_string(root->val) + "," + serialize(root->left) + "," + serialize(root->right);
}
TreeNode* deserialize(string data) {
    int i = 0;
    function<TreeNode*()> des = [&]() {
        if (i >= data.size() || data[i] == 'N') { i += 2; return (TreeNode*)nullptr; }
        int val = 0, sign = 1;
        if (data[i] == '-') { sign = -1; i++; }
        while (i < data.size() && isdigit(data[i])) val = val * 10 + (data[i++] - '0');
        i++;
        TreeNode* node = new TreeNode(val * sign);
        node->left = des(); node->right = des();
        return node;
    };
    return des();
}
